function validate([s]) {
  if (typeof s !== 'string') return 's must be a string.';
  if (s.length < 2 || s.length > 100) return 's needs 2 to 100 characters.';
  if (!/^[a-z]+$/.test(s)) return 's may only use lowercase English letters.';
  return null;
}

