function maximumLengthSubstring(s) {
  let best = 0;
  for (let i = 0; i < s.length; i++) {
    for (let j = i + 1; j <= s.length; j++) {
      const piece = s.slice(i, j);
      const ok = [...new Set(piece)].every(ch => piece.split(ch).length - 1 <= 2);
      if (ok && piece.length > best) best = piece.length;
    }
  }
  return best;
}

