function generate(rand, size) {
  const n = size === 'large' ? 100 : 2 + Math.floor(rand() * 10);
  const alphabet = size === 'large' ? 1 + Math.floor(rand() * 26) : 1 + Math.floor(rand() * 5);
  let s = '';
  for (let i = 0; i < n; i++) s += String.fromCharCode(97 + Math.floor(rand() * alphabet));
  return [s];
}
